function reverseNumber(n) {
  const sign = n < 0 ? -1 : 1;
  n = Math.abs(n);
  let result = 0;

  while (n > 0) {
    const digit = n % 10;
    result = result * 10 + digit;
    n = Math.floor(n / 10);
  }

  return sign * result;
}

