function minWindow(s, t) {
  if (!s || !t) return '';
  const tCount = {};
  for (const ch of t) tCount[ch] = (tCount[ch] || 0) + 1;
  let required = Object.keys(tCount).length;
  let left = 0, right = 0, formed = 0;
  const windowCounts = {};
  let ans = [-1, 0, 0];
  while (right < s.length) {
    const c = s[right];
    windowCounts[c] = (windowCounts[c] || 0) + 1;
    if (tCount[c] && windowCounts[c] === tCount[c]) formed++;
    while (left <= right && formed === required) {
      const cLeft = s[left];
      if (ans[0] === -1 || right - left + 1 < ans[0]) ans = [right - left + 1, left, right];
      windowCounts[cLeft]--;
      if (tCount[cLeft] && windowCounts[cLeft] < tCount[cLeft]) formed--;
      left++;
    }
    right++;
  }
  return ans[0] === -1 ? '' : s.substring(ans[1], ans[2] + 1);
}

