            if (set.contains(word)) {
                List<String> subs = dfs(s, end, set, memo);
                for (String sub : subs) {
                    res.add(word + (sub.isEmpty() ? "" : " " + sub));
                }
            }
        }
        memo.put(start, res);
        return res;
    }
