        int[] cuts = new int[n];
        for (int i = 0; i < n; i++) cuts[i] = i;
        for (int i = 0; i < n; i++) {
            expand(s, i, i, cuts);
            expand(s, i, i + 1, cuts);
        }
        return cuts[n - 1];
    }
    private static void expand(String s, int left, int right, int[] cuts) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
