    if (w1.length > w2.length && w1.startsWith(w2)) return '';
    for (let j = 0; j < Math.min(w1.length, w2.length); j++) {
      if (w1[j] !== w2[j]) {
        if (!adj[w1[j]].has(w2[j])) {
          adj[w1[j]].add(w2[j]);
          inDegree[w2[j]]++;
        }
        break;
      }
    }
  }
  const queue = [];
  for (const c in inDegree) if (inDegree[c] === 0) queue.push(c);
  let res = '';
  while (queue.length) {
    const c = queue.shift();
    res += c;
    for (const neighbor of adj[c]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) queue.push(neighbor);
    }
  }
  return res.length === Object.keys(inDegree).length ? res : '';
}

