    }
}

function findLadders(beginWord, endWord, wordList) {
  const wordSet = new Set(wordList);
  if (!wordSet.has(endWord)) return [];
  wordSet.add(beginWord);
  const dist = new Map();
  const queue = [beginWord];
  dist.set(beginWord, 0);
  while (queue.length) {
    const curr = queue.shift();
    const d = dist.get(curr);
    for (let i = 0; i < curr.length; i++) {
      for (let c = 97; c <= 122; c++) {
        const next = curr.substring(0, i) + String.fromCharCode(c) + curr.substring(i + 1);
        if (wordSet.has(next) && !dist.has(next)) {
          dist.set(next, d + 1);
          queue.push(next);
        }
      }
    }
  }
  if (!dist.has(endWord)) return [];
  const res = [];
  function dfs(word, path) {
    if (word === beginWord) {
      res.push([beginWord, ...path]);
      return;
    }
    const d = dist.get(word);
    for (let i = 0; i < word.length; i++) {
      for (let c = 97; c <= 122; c++) {
        const prev = word.substring(0, i) + String.fromCharCode(c) + word.substring(i + 1);
        if (dist.get(prev) === d - 1) {
          dfs(prev, [word, ...path]);
        }
      }
    }
  }
  dfs(endWord, []);
  return res;
}

