public class Solution {
    public static List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        List<List<String>> res = new ArrayList<>();
        if (!wordSet.contains(endWord)) return res;
        Map<String, Integer> dist = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        queue.add(beginWord);
        dist.put(beginWord, 0);
        while (!queue.isEmpty()) {
            String curr = queue.poll();
            int d = dist.get(curr);
            char[] chars = curr.toCharArray();
            for (int i = 0; i < chars.length; i++) {
                char orig = chars[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    chars[i] = c;
                    String next = new String(chars);
                    if (wordSet.contains(next) && !dist.containsKey(next)) {
                        dist.put(next, d + 1);
                        queue.add(next);
                    }
                }
                chars[i] = orig;
            }
        }
        if (!dist.containsKey(endWord)) return res;
        dfs(endWord, beginWord, dist, new ArrayList<>(Arrays.asList(endWord)), res);
        return res;
    }
    private static void dfs(String word, String beginWord, Map<String, Integer> dist, List<String> path, List<List<String>> res) {
        if (word.equals(beginWord)) {
            List<String> copy = new ArrayList<>(path);
            Collections.reverse(copy);
            res.add(copy);
            return;
        }
        int d = dist.get(word);
        char[] chars = word.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char orig = chars[i];
            for (char c = 'a'; c <= 'z'; c++) {
                chars[i] = c;
                String prev = new String(chars);
                if (dist.getOrDefault(prev, -1) == d - 1) {
                    path.add(prev);
                    dfs(prev, beginWord, dist, path, res);
                    path.remove(path.size() - 1);
                }
            }
            chars[i] = orig;
        }
    }
}

