def find_ladders(begin_word: str, end_word: str, word_list: list[str]) -> list[list[str]]:
    word_set = set(word_list)
    if end_word not in word_set: return []
    dist = {begin_word: 0}
    queue = deque([begin_word])
    while queue:
        curr = queue.popleft()
        d = dist[curr]
        for i in range(len(curr)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = curr[:i] + c + curr[i+1:]
                if next_word in word_set and next_word not in dist:
                    dist[next_word] = d + 1
                    queue.append(next_word)
    if end_word not in dist: return []
    res = []
    def dfs(word, path):
        if word == begin_word:
            res.append([begin_word] + path)
            return
        d = dist[word]
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                prev = word[:i] + c + word[i+1:]
                if dist.get(prev) == d - 1:
                    dfs(prev, [word] + path)
    dfs(end_word, [])
    return res

function criticalConnections(n, connections) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of connections) {
    adj[u].push(v); adj[v].push(u);
  }
  const disc = new Array(n).fill(-1);
  const low = new Array(n).fill(-1);
  const bridges = [];
  let time = 0;
  function dfs(u, parent) {
    disc[u] = low[u] = time++;
    for (const v of adj[u]) {
      if (v === parent) continue;
      if (disc[v] === -1) {
        dfs(v, u);
        low[u] = Math.min(low[u], low[v]);
        if (low[v] > disc[u]) bridges.push([u, v]);
      } else {
        low[u] = Math.min(low[u], disc[v]);
      }
    }
  }
  dfs(0, -1);
  return bridges;
}

