public class Solution {
    private static int time = 0;
    public static List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (List<Integer> c : connections) {
            adj[c.get(0)].add(c.get(1));
            adj[c.get(1)].add(c.get(0));
        }
        int[] disc = new int[n]; Arrays.fill(disc, -1);
        int[] low = new int[n]; Arrays.fill(low, -1);
        List<List<Integer>> bridges = new ArrayList<>();
        time = 0;
        dfs(0, -1, adj, disc, low, bridges);
        return bridges;
    }
    private static void dfs(int u, int parent, List<Integer>[] adj, int[] disc, int[] low, List<List<Integer>> bridges) {
        disc[u] = low[u] = time++;
        for (int v : adj[u]) {
            if (v == parent) continue;
            if (disc[v] == -1) {
                dfs(v, u, adj, disc, low, bridges);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) bridges.add(Arrays.asList(u, v));
            } else {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }
}

