function shortestPathAllKeys(grid) {
  const m = grid.length, n = grid[0].length;
  let startR = 0, startC = 0, keyCount = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      const ch = grid[r][c];
      if (ch === '@') { startR = r; startC = c; }
      else if (ch >= 'a' && ch <= 'f') keyCount++;
    }
  }
  const targetMask = (1 << keyCount) - 1;
  const queue = [[startR, startC, 0, 0]];
  const visited = new Set([`${startR},${startC},0`]);
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  while (queue.length) {
    const [r, c, mask, steps] = queue.shift();
    if (mask === targetMask) return steps;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= m || nc >= n || grid[nr][nc] === '#') continue;
      const ch = grid[nr][nc];
      let newMask = mask;
      if (ch >= 'a' && ch <= 'f') newMask |= (1 << (ch.charCodeAt(0) - 97));
      if (ch >= 'A' && ch <= 'F' && !(mask & (1 << (ch.charCodeAt(0) - 65)))) continue;
      const keyState = `${nr},${nc},${newMask}`;
      if (!visited.has(keyState)) {
        visited.add(keyState);
        queue.push([nr, nc, newMask, steps + 1]);
      }
    }
  }
  return -1;
}

