def shortest_path_all_keys(grid: list[str]) -> int:
    m, n = len(grid), len(grid[0])
    start_r = start_c = key_count = 0
    for r in range(m):
        for c in range(n):
            ch = grid[r][c]
            if ch == '@': start_r, start_c = r, c
            elif 'a' <= ch <= 'f': key_count += 1
    target_mask = (1 << key_count) - 1
    queue = deque([(start_r, start_c, 0, 0)])
    visited = {(start_r, start_c, 0)}
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    while queue:
        r, c, mask, steps = queue.popleft()
        if mask == target_mask: return steps
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] != '#':
                ch = grid[nr][nc]
                new_mask = mask
                if 'a' <= ch <= 'f': new_mask |= (1 << (ord(ch) - ord('a')))
                if 'A' <= ch <= 'F' and not (mask & (1 << (ord(ch) - ord('A')))): continue
                if (nr, nc, new_mask) not in visited:
                    visited.add((nr, nc, new_mask))
                    queue.append((nr, nc, new_mask, steps + 1))
    return -1

function trapRainWater(heightMap) {
  const m = heightMap.length, n = heightMap[0].length;
  if (m < 3 || n < 3) return 0;
  const visited = Array.from({ length: m }, () => new Array(n).fill(false));
  const heap = []; // Simulated Min-heap array
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (r === 0 || r === m - 1 || c === 0 || c === n - 1) {
        visited[r][c] = true;
        heap.push([heightMap[r][c], r, c]);
      }
    }
  }
  heap.sort((a, b) => a[0] - b[0]);
  let water = 0, maxBoundary = 0;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  while (heap.length) {
    const [h, r, c] = heap.shift();
    maxBoundary = Math.max(maxBoundary, h);
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && !visited[nr][nc]) {
        visited[nr][nc] = true;
        if (heightMap[nr][nc] < maxBoundary) water += maxBoundary - heightMap[nr][nc];
        heap.push([heightMap[nr][nc], nr, nc]);
        heap.sort((a, b) => a[0] - b[0]);
      }
    }
  }
  return water;
}

