function minCost(grid) {
  const m = grid.length, n = grid[0].length;
  const cost = Array.from({ length: m }, () => new Array(n).fill(Infinity));
  cost[0][0] = 0;
  const deque = [[0, 0]];
  const dirs = [[0,1],[0,-1],[1,0],[-1,0]]; // 1:right, 2:left, 3:down, 4:up
  while (deque.length) {
    const [r, c] = deque.shift();
    if (r === m - 1 && c === n - 1) return cost[r][c];
    for (let i = 0; i < 4; i++) {
      const nr = r + dirs[i][0], nc = c + dirs[i][1];
      if (nr >= 0 && nc >= 0 && nr < m && nc < n) {
        const w = (grid[r][c] === i + 1) ? 0 : 1;
        if (cost[r][c] + w < cost[nr][nc]) {
          cost[nr][nc] = cost[r][c] + w;
          if (w === 0) deque.unshift([nr, nc]);
          else deque.push([nr, nc]);
        }
      }
    }
  }
  return cost[m - 1][n - 1];
}

