public class LFUCache {
    class Node {
        int key, val, freq;
        Node(int key, int val) { this.key = key; this.val = val; this.freq = 1; }
    }
    private final int capacity;
    private int minFreq = 0;
    private Map<Integer, Node> keyMap = new HashMap<>();
    private Map<Integer, LinkedHashSet<Node>> freqMap = new HashMap<>();
    public LFUCache(int capacity) { this.capacity = capacity; }
    public int get(int key) {
        if (!keyMap.containsKey(key)) return -1;
        Node node = keyMap.get(key);
        update(node);
        return node.val;
    }
    private void update(Node node) {
        int oldFreq = node.freq;
        LinkedHashSet<Node> oldList = freqMap.get(oldFreq);
        oldList.remove(node);
        if (oldFreq == minFreq && oldList.isEmpty()) minFreq++;
        node.freq++;
        freqMap.putIfAbsent(node.freq, new LinkedHashSet<>());
        freqMap.get(node.freq).add(node);
    }
    public void put(int key, int value) {
        if (capacity == 0) return;
        if (keyMap.containsKey(key)) {
            Node node = keyMap.get(key);
            node.val = value;
            update(node);
        } else {
            if (keyMap.size() >= capacity) {
                LinkedHashSet<Node> minList = freqMap.get(minFreq);
                Node evict = minList.iterator().next();
                minList.remove(evict);
                keyMap.remove(evict.key);
            }
            Node newNode = new Node(key, value);
            keyMap.put(key, newNode);
            minFreq = 1;
            freqMap.putIfAbsent(1, new LinkedHashSet<>());
            freqMap.get(1).add(newNode);
        }
    }
}

