class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        self.key_map = {}
        self.freq_map = defaultdict(OrderedDict)

    def _update(self, node):
        old_freq = node.freq
        del self.freq_map[old_freq][node.key]
        if old_freq == self.min_freq and not self.freq_map[old_freq]:
            self.min_freq += 1
        node.freq += 1
        self.freq_map[node.freq][node.key] = node

    def get(self, key: int) -> int:
        if key not in self.key_map: return -1
        node = self.key_map[key]
        self._update(node)
        return node.val

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0: return
        if key in self.key_map:
            node = self.key_map[key]
            node.val = value
            self._update(node)
        else:
            if len(self.key_map) >= self.capacity:
                evict_key, evict_node = self.freq_map[self.min_freq].popitem(last=False)
                del self.key_map[evict_key]
            new_node = Node(key, value)
            self.key_map[key] = new_node
            self.min_freq = 1
            self.freq_map[1][key] = new_node

