        dfs(nr, nc, node);
      }
    }
    board[r][c] = ch;
  }
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, root);
    }
  }
  return res;
}

interface TrieNode {
  children: Record<string, TrieNode>;
  word: string | null;
}

function findWords(board: string[][], words: string[]): string[] {
  const root: TrieNode = { children: {}, word: null };
  for (const w of words) {
    let node = root;
    for (const c of w) {
      if (!node.children[c]) node.children[c] = { children: {}, word: null };
      node = node.children[c];
    }
    node.word = w;
  }
  const res: string[] = [];
  const m = board.length, n = board[0].length;
  function dfs(r: number, c: number, node: TrieNode) {
    const ch = board[r][c];
    if (!node.children[ch]) return;
    node = node.children[ch];
    if (node.word) {
      res.push(node.word);
      node.word = null;
    }
    board[r][c] = '#';
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < m && nc < n && board[nr][nc] !== '#') {
        dfs(nr, nc, node);
      }
    }
    board[r][c] = ch;
  }
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, root);
    }
  }
  return res;
}

import java.util.*;

public class Solution {
    class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        String word = null;
    }
    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode node = root;
            for (char c : w.toCharArray()) {
                node.children.putIfAbsent(c, new TrieNode());
                node = node.children.get(c);
            }
            node.word = w;
        }
        List<String> res = new ArrayList<>();
        int m = board.length, n = board[0].length;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                dfs(board, r, c, root, res);
            }
        }
        return res;
    }
    private void dfs(char[][] board, int r, int c, TrieNode node, List<String> res) {
        char ch = board[r][c];
        if (!node.children.containsKey(ch)) return;
        node = node.children.get(ch);
        if (node.word != null) {
            res.add(node.word);
            node.word = null;
        }
        board[r][c] = '#';
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nc >= 0 && nr < board.length && nc < board[0].length && board[nr][nc] != '#') {
                dfs(board, nr, nc, node, res);
            }
        }
        board[r][c] = ch;
    }
}

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    trie = {}
    for w in words:
        node = trie
        for c in w:
            node = node.setdefault(c, {})
        node['$'] = w
    m, n = len(board), len(board[0])
    res = []
    def dfs(r, c, parent):
        ch = board[r][c]
        curr = parent[ch]
        if '$' in curr:
            res.append(curr['$'])
            del curr['$']
        board[r][c] = '#'
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] in curr:
                dfs(nr, nc, curr)
        board[r][c] = ch
    for r in range(m):
        for c in range(n):
            if board[r][c] in trie:
                dfs(r, c, trie)
    return res

