import java.util.*;

public class Solution {
    class Pair {
        int val, idx;
        Pair(int val, int idx) { this.val = val; this.idx = idx; }
    }
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        Integer[] counts = new Integer[n];
        Arrays.fill(counts, 0);
        Pair[] items = new Pair[n];
        for (int i = 0; i < n; i++) items[i] = new Pair(nums[i], i);
        mergeSort(items, 0, n - 1, counts);
        return Arrays.asList(counts);
    }
    private void mergeSort(Pair[] items, int left, int right, Integer[] counts) {
        if (left >= right) return;
        int mid = left + (right - left) / 2;
        mergeSort(items, left, mid, counts);
        mergeSort(items, mid + 1, right, counts);
        List<Pair> merged = new ArrayList<>();
        int i = left, j = mid + 1, rightCount = 0;
        while (i <= mid && j <= right) {
            if (items[j].val < items[i].val) {
                rightCount++;
                merged.add(items[j++]);
            } else {
                counts[items[i].idx] += rightCount;
                merged.add(items[i++]);
            }
        }
        while (i <= mid) {
            counts[items[i].idx] += rightCount;
            merged.add(items[i++]);
        }
        while (j <= right) merged.add(items[j++]);
        for (int k = 0; k < merged.size(); k++) items[left + k] = merged.get(k);
    }
}

function findMedianSortedArrays(nums1, nums2) {
  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);
  const m = nums1.length, n = nums2.length;
  let low = 0, high = m;
  while (low <= high) {
    const i = Math.floor((low + high) / 2);
    const j = Math.floor((m + n + 1) / 2) - i;
    const maxLeft1 = i === 0 ? -Infinity : nums1[i - 1];
    const minRight1 = i === m ? Infinity : nums1[i];
    const maxLeft2 = j === 0 ? -Infinity : nums2[j - 1];
    const minRight2 = j === n ? Infinity : nums2[j];
    if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
      if ((m + n) % 2 === 1) return Math.max(maxLeft1, maxLeft2);
      return (Math.max(maxLeft1, maxLeft2) + Math.min(minRight1, minRight2)) / 2;
    } else if (maxLeft1 > minRight2) {
      high = i - 1;
    } else {
      low = i + 1;
    }
  }
  return 0.0;
}

