public class Solution {
    public static double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);
        int m = nums1.length, n = nums2.length;
        int low = 0, high = m;
        while (low <= high) {
            int i = low + (high - low) / 2;
            int j = (m + n + 1) / 2 - i;
            int maxLeft1 = (i == 0) ? Integer.MIN_VALUE : nums1[i - 1];
            int minRight1 = (i == m) ? Integer.MAX_VALUE : nums1[i];
            int maxLeft2 = (j == 0) ? Integer.MIN_VALUE : nums2[j - 1];
            int minRight2 = (j == n) ? Integer.MAX_VALUE : nums2[j];
            if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
                if ((m + n) % 2 == 1) return Math.max(maxLeft1, maxLeft2);
                return (Math.max(maxLeft1, maxLeft2) + Math.min(minRight1, minRight2)) / 2.0;
            } else if (maxLeft1 > minRight2) {
                high = i - 1;
            } else {
                low = i + 1;
            }
        }
        return 0.0;
    }
}

def find_median_sorted_arrays(nums1: list[int], nums2: list[int]) -> float:
    if len(nums1) > len(nums2):
        return find_median_sorted_arrays(nums2, nums1)
    m, n = len(nums1), len(nums2)
    low, high = 0, m
    while low <= high:
        i = (low + high) // 2
        j = (m + n + 1) // 2 - i
        max_left1 = float('-inf') if i == 0 else nums1[i - 1]
        min_right1 = float('inf') if i == m else nums1[i]
        max_left2 = float('-inf') if j == 0 else nums2[j - 1]
        min_right2 = float('inf') if j == n else nums2[j]
        if max_left1 <= min_right2 and max_left2 <= min_right1:
            if (m + n) % 2 == 1:
                return float(max(max_left1, max_left2))
            return (max(max_left1, max_left2) + min(min_right1, min_right2)) / 2.0
        elif max_left1 > min_right2:
            high = i - 1
        else:
            low = i + 1
    return 0.0

function mincostToHireWorkers(quality, wage, k) {
  const workers = quality.map((q, i) => ({ q, r: wage[i] / q }));
  workers.sort((a, b) => a.r - b.r);
  const heap = []; // Simulated Max-Heap
  let totalQuality = 0;
  let minCost = Infinity;
  for (const w of workers) {
    heap.push(w.q);
    heap.sort((a, b) => b - a);
    totalQuality += w.q;
    if (heap.length > k) {
      totalQuality -= heap.shift();
    }
    if (heap.length === k) {
      minCost = Math.min(minCost, totalQuality * w.r);
    }
  }
  return minCost;
}

type Worker = { q: number; r: number };

function mincostToHireWorkers(quality: number[], wage: number[], k: number): number {
  const workers: Worker[] = quality.map((q, i) => ({ q, r: wage[i] / q }));
  workers.sort((a, b) => a.r - b.r);
  const heap: number[] = [];
  let totalQuality = 0;
  let minCost = Infinity;
  for (const w of workers) {
    heap.push(w.q);
    heap.sort((a, b) => b - a);
    totalQuality += w.q;
    if (heap.length > k) {
      totalQuality -= heap.shift()!;
    }
    if (heap.length === k) {
      minCost = Math.min(minCost, totalQuality * w.r);
    }
  }
  return minCost;
}

import java.util.*;

public class Solution {
    class Worker {
        double q, r;
        Worker(double q, double r) { this.q = q; this.r = r; }
    }
    public double mincostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        Worker[] workers = new Worker[n];
        for (int i = 0; i < n; i++) workers[i] = new Worker(quality[i], (double) wage[i] / quality[i]);
        Arrays.sort(workers, (a, b) -> Double.compare(a.r, b.r));
        PriorityQueue<Double> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        double totalQuality = 0, minCost = Double.MAX_VALUE;
        for (Worker w : workers) {
            maxHeap.add(w.q);
            totalQuality += w.q;
            if (maxHeap.size() > k) {
                totalQuality -= maxHeap.poll();
            }
            if (maxHeap.size() == k) {
                minCost = Math.min(minCost, totalQuality * w.r);
            }
        }
        return minCost;
    }
}

function getSkyline(buildings) {
  const events = [];
  for (const [l, r, h] of buildings) {
    events.push([l, -h]);
    events.push([r, h]);
  }
  events.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
  const res = [];
  const heights = [0];
  let prevMax = 0;
  for (const [x, h] of events) {
    if (h < 0) {
      heights.push(-h);
    } else {
      const idx = heights.indexOf(h);
      if (idx !== -1) heights.splice(idx, 1);
    }
    heights.sort((a, b) => b - a);
    const currentMax = heights[0];
    if (currentMax !== prevMax) {
      res.push([x, currentMax]);
      prevMax = currentMax;
    }
  }
  return res;
}

