        const mask = 1 << val;
        const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
        rows[r] |= mask; cols[c] |= mask; boxes[b] |= mask;
      }
    }
  }
  function solve(r, c) {
    if (r === 9) return true;
    if (c === 9) return solve(r + 1, 0);
    if (board[r][c] !== '.') return solve(r, c + 1);
    const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
    for (let val = 1; val <= 9; val++) {
      const mask = 1 << val;
      if (!(rows[r] & mask) && !(cols[c] & mask) && !(boxes[b] & mask)) {
        rows[r] |= mask; cols[c] |= mask; boxes[b] |= mask;
        board[r][c] = String(val);
        if (solve(r, c + 1)) return true;
        rows[r] &= ~mask; cols[c] &= ~mask; boxes[b] &= ~mask;
        board[r][c] = '.';
      }
    }
    return false;
  }
  solve(0, 0);
}

