        if (c == 9) return solve(r + 1, 0, board, rows, cols, boxes);
        if (board[r][c] != '.') return solve(r, c + 1, board, rows, cols, boxes);
        int b = (r / 3) * 3 + (c / 3);
        for (int val = 1; val <= 9; val++) {
