            if ((rows[r] & mask) == 0 && (cols[c] & mask) == 0 && (boxes[b] & mask) == 0) {
                rows[r] |= mask; cols[c] |= mask; boxes[b] |= mask;
                board[r][c] = (char) (val + '0');
