function addOperators(num, target) {
  const res = [];
  function dfs(index, path, evalVal, multed) {
    if (index === num.length) {
      if (evalVal === target) res.push(path);
      return;
    }
    for (let i = index; i < num.length; i++) {
      if (i !== index && num[index] === '0') break;
      const str = num.substring(index, i + 1);
      const curr = Number(str);
      if (index === 0) {
        dfs(i + 1, str, curr, curr);
      } else {
        dfs(i + 1, path + '+' + str, evalVal + curr, curr);
        dfs(i + 1, path + '-' + str, evalVal - curr, -curr);
        dfs(i + 1, path + '*' + str, evalVal - multed + multed * curr, multed * curr);
      }
    }
  }
  dfs(0, '', 0, 0);
  return res;
}

