function calculate(s) {
  let sum = 0, sign = 1;
  const stack = [];
  let i = 0;
  while (i < s.length) {
    const ch = s[i];
    if (ch >= '0' && ch <= '9') {
      let num = 0;
      while (i < s.length && s[i] >= '0' && s[i] <= '9') {
        num = num * 10 + Number(s[i++]);
      }
      sum += sign * num;
      continue;
    } else if (ch === '+') sign = 1;
    else if (ch === '-') sign = -1;
    else if (ch === '(') {
      stack.push(sum);
      stack.push(sign);
      sum = 0; sign = 1;
    } else if (ch === ')') {
      sum = stack.pop() * sum + stack.pop();
    }
    i++;
  }
  return sum;
}

