  let res = '', i = 0;
  while (num > 0) {
    if (num % 1000 !== 0) {
      res = helper(num % 1000) + THOUSANDS[i] + ' ' + res;
    }
    num = Math.floor(num / 1000);
    i++;
  }
  return res.trim().replace(/\s+/g, ' ');
}

