function shortestSubarray(nums, k) {
  const n = nums.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
  let minLen = Infinity;
  const deque = [];
  for (let i = 0; i <= n; i++) {
    while (deque.length && P[i] - P[deque[0]] >= k) {
      minLen = Math.min(minLen, i - deque.shift());
    }
    while (deque.length && P[i] <= P[deque[deque.length - 1]]) {
      deque.pop();
    }
    deque.push(i);
  }
  return minLen === Infinity ? -1 : minLen;
}

