public class Solution {
    public static int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        int minLen = n + 1;
        Deque<Integer> deque = new ArrayDeque<>();
        for (int i = 0; i <= n; i++) {
            while (!deque.isEmpty() && P[i] - P[deque.peekFirst()] >= k) {
                minLen = Math.min(minLen, i - deque.pollFirst());
            }
            while (!deque.isEmpty() && P[i] <= P[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.offerLast(i);
        }
        return minLen <= n ? minLen : -1;
    }
}

function maxSumSubmatrix(matrix, k) {
  const m = matrix.length, n = matrix[0].length;
  let maxSum = -Infinity;
  for (let l = 0; l < n; l++) {
    const rowSums = new Array(m).fill(0);
    for (let r = l; r < n; r++) {
      for (let i = 0; i < m; i++) rowSums[i] += matrix[i][r];
      const set = [0];
      let curr = 0;
      for (const sum of rowSums) {
        curr += sum;
        // Binary search for smallest val >= curr - k
        const target = curr - k;
        let low = 0, high = set.length - 1, match = -1;
        while (low <= high) {
          const mid = Math.floor((low + high) / 2);
          if (set[mid] >= target) { match = set[mid]; high = mid - 1; }
          else low = mid + 1;
        }
        if (match !== -1) maxSum = Math.max(maxSum, curr - match);
        // Insert curr in sorted array
        let pos = 0;
        while (pos < set.length && set[pos] < curr) pos++;
        set.splice(pos, 0, curr);
      }
    }
  }
  return maxSum;
}

