function countRangeSum(nums, lower, upper) {
  const n = nums.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
  function mergeSort(left, right) {
    if (right - left <= 1) return 0;
    const mid = Math.floor((left + right) / 2);
    let count = mergeSort(left, mid) + mergeSort(mid, right);
    let j = mid, k = mid;
    for (let i = left; i < mid; i++) {
      while (j < right && P[j] - P[i] < lower) j++;
      while (k < right && P[k] - P[i] <= upper) k++;
      count += k - j;
    }
    const sorted = [];
    let l = left, r = mid;
    while (l < mid && r < right) {
      if (P[l] <= P[r]) sorted.push(P[l++]);
      else sorted.push(P[r++]);
    }
    while (l < mid) sorted.push(P[l++]);
    while (r < right) sorted.push(P[r++]);
    for (let i = 0; i < sorted.length; i++) P[left + i] = sorted[i];
    return count;
  }
  return mergeSort(0, n + 1);
}

