public class Solution {
    public static int countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        return mergeSort(P, 0, n + 1, lower, upper);
    }
    private static int mergeSort(long[] P, int left, int right, int lower, int upper) {
        if (right - left <= 1) return 0;
        int mid = left + (right - left) / 2;
        int count = mergeSort(P, left, mid, lower, upper) + mergeSort(P, mid, right, lower, upper);
        int j = mid, k = mid;
        for (int i = left; i < mid; i++) {
            while (j < right && P[j] - P[i] < lower) j++;
            while (k < right && P[k] - P[i] <= upper) k++;
            count += k - j;
        }
        long[] sorted = new long[right - left];
        int l = left, r = mid, idx = 0;
        while (l < mid && r < right) {
            if (P[l] <= P[r]) sorted[idx++] = P[l++];
            else sorted[idx++] = P[r++];
        }
        while (l < mid) sorted[idx++] = P[l++];
        while (r < right) sorted[idx++] = P[r++];
        System.arraycopy(sorted, 0, P, left, sorted.length);
        return count;
    }
}

function mergeStones(stones, k) {
  const n = stones.length;
  if ((n - 1) % (k - 1) !== 0) return -1;
  const pref = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + stones[i];
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = k; len <= n; len++) {
    for (let i = 0; i <= n - len; i++) {
      const j = i + len - 1;
      dp[i][j] = Infinity;
      for (let m = i; m < j; m += k - 1) {
        dp[i][j] = Math.min(dp[i][j], dp[i][m] + dp[m + 1][j]);
      }
      if ((j - i) % (k - 1) === 0) {
        dp[i][j] += pref[j + 1] - pref[i];
      }
    }
  }
  return dp[0][n - 1];
}

