function cherryPickup(grid) {
  const rows = grid.length, cols = grid[0].length;
  const memo = Map();
  function dfs(r, c1, c2) {
    if (c1 < 0 || c1 >= cols || c2 < 0 || c2 >= cols) return -Infinity;
    if (r === rows) return 0;
    const key = `${r},${c1},${c2}`;
    if (memo.has(key)) return memo.get(key);
    let cherries = c1 === c2 ? grid[r][c1] : grid[r][c1] + grid[r][c2];
    let maxNext = -Infinity;
    for (let d1 = -1; d1 <= 1; d1++) {
      for (let d2 = -1; d2 <= 1; d2++) {
        maxNext = Math.max(maxNext, dfs(r + 1, c1 + d1, c2 + d2));
      }
    }
    const res = cherries + maxNext;
    memo.set(key, res);
    return res;
  }
  return dfs(0, 0, cols - 1);
}

