public class Solution {
    public static int cherryPickup(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int[][][] dp = new int[rows][cols][cols];
        for (int[][] r : dp) for (int[] c : r) Arrays.fill(c, -1);
        return dfs(0, 0, cols - 1, grid, dp);
    }
    private static int dfs(int r, int c1, int c2, int[][] grid, int[][][] dp) {
        int rows = grid.length, cols = grid[0].length;
        if (c1 < 0 || c1 >= cols || c2 < 0 || c2 >= cols) return -1000000;
        if (r == rows) return 0;
        if (dp[r][c1][c2] != -1) return dp[r][c1][c2];
        int cherries = (c1 == c2) ? grid[r][c1] : grid[r][c1] + grid[r][c2];
        int maxNext = -1000000;
        for (int d1 = -1; d1 <= 1; d1++) {
            for (int d2 = -1; d2 <= 1; d2++) {
                maxNext = Math.max(maxNext, dfs(r + 1, c1 + d1, c2 + d2, grid, dp));
            }
        }
        return dp[r][c1][c2] = cherries + maxNext;
    }
}

def cherry_pickup(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    memo = {}
    def dfs(r, c1, c2):
        if c1 < 0 or c1 >= cols or c2 < 0 or c2 >= cols: return float('-inf')
        if r == rows: return 0
        if (r, c1, c2) in memo: return memo[(r, c1, c2)]
        cherries = grid[r][c1] if c1 == c2 else grid[r][c1] + grid[r][c2]
        max_next = max(dfs(r + 1, c1 + d1, c2 + d2) for d1 in (-1,0,1) for d2 in (-1,0,1))
        memo[(r, c1, c2)] = cherries + max_next
        return memo[(r, c1, c2)]
    return dfs(0, 0, cols - 1)

function shortestPathLength(graph) {
  const n = graph.length;
  const targetMask = (1 << n) - 1;
  const queue = [];
  const visited = new Set();
  for (let i = 0; i < n; i++) {
    const mask = 1 << i;
    queue.push([i, mask, 0]);
    visited.add(`${i},${mask}`);
  }
  while (queue.length) {
    const [node, mask, dist] = queue.shift();
    if (mask === targetMask) return dist;
    for (const neighbor of graph[node]) {
      const nextMask = mask | (1 << neighbor);
      const state = `${neighbor},${nextMask}`;
      if (!visited.has(state)) {
        visited.add(state);
        queue.push([neighbor, nextMask, dist + 1]);
      }
    }
  }
  return 0;
}

