import java.util.*;

public class Solution {
    public static int shortestPathLength(int[][] graph) {
        int n = graph.length;
        int targetMask = (1 << n) - 1;
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][1 << n];
        for (int i = 0; i < n; i++) {
            int mask = 1 << i;
            queue.add(new int[]{i, mask, 0});
            visited[i][mask] = true;
        }
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int node = curr[0], mask = curr[1], dist = curr[2];
            if (mask == targetMask) return dist;
            for (int neighbor : graph[node]) {
                int nextMask = mask | (1 << neighbor);
                if (!visited[neighbor][nextMask]) {
                    visited[neighbor][nextMask] = true;
                    queue.add(new int[]{neighbor, nextMask, dist + 1});
                }
            }
        }
        return 0;
    }
}

from collections import deque

def shortest_path_length(graph: list[list[int]]) -> int:
    n = len(graph)
    target_mask = (1 << n) - 1
    queue = deque([(i, 1 << i, 0) for i in range(n)])
    visited = {(i, 1 << i) for i in range(n)}
    while queue:
        node, mask, dist = queue.popleft()
        if mask == target_mask: return dist
        for neighbor in graph[node]:
            next_mask = mask | (1 << neighbor)
            if (neighbor, next_mask) not in visited:
                visited.add((neighbor, next_mask))
                queue.append((neighbor, next_mask, dist + 1))
    return 0

class FreqStack {
  constructor() {
    this.freq = new Map();
    this.group = new Map();
    this.maxFreq = 0;
  }
  push(val) {
    const f = (this.freq.get(val) || 0) + 1;
    this.freq.set(val, f);
    this.maxFreq = Math.max(this.maxFreq, f);
    if (!this.group.has(f)) this.group.set(f, []);
    this.group.get(f).push(val);
  }
  pop() {
    const stack = this.group.get(this.maxFreq);
    const val = stack.pop();
    this.freq.set(val, this.freq.get(val) - 1);
    if (stack.length === 0) this.maxFreq--;
    return val;
  }
}

class FreqStack {
  private freq = new Map<number, number>();
  private group = new Map<number, number[]>();
  private maxFreq = 0;
  push(val: number): void {
    const f = (this.freq.get(val) || 0) + 1;
    this.freq.set(val, f);
    this.maxFreq = Math.max(this.maxFreq, f);
    if (!this.group.has(f)) this.group.set(f, []);
    this.group.get(f)!.push(val);
  }
  pop(): number {
    const stack = this.group.get(this.maxFreq)!;
    const val = stack.pop()!;
    this.freq.set(val, this.freq.get(val)! - 1);
    if (stack.length === 0) this.maxFreq--;
    return val;
  }
}

import java.util.*;

public class FreqStack {
    private Map<Integer, Integer> freq = new HashMap<>();
    private Map<Integer, Stack<Integer>> group = new HashMap<>();
    private int maxFreq = 0;
    public void push(int val) {
        int f = freq.getOrDefault(val, 0) + 1;
        freq.put(val, f);
        maxFreq = Math.max(maxFreq, f);
        group.putIfAbsent(f, new Stack<>());
        group.get(f).push(val);
    }
    public int pop() {
        int val = group.get(maxFreq).pop();
        freq.put(val, freq.get(val) - 1);
        if (group.get(maxFreq).isEmpty()) maxFreq--;
        return val;
    }
}

function minRefuelStops(target, startFuel, stations) {
  const heap = []; // Max-Heap simulated
  let maxReach = startFuel, stops = 0, idx = 0;
  while (maxReach < target) {
    while (idx < stations.length && stations[idx][0] <= maxReach) {
      heap.push(stations[idx][1]);
      heap.sort((a, b) => b - a);
      idx++;
    }
    if (heap.length === 0) return -1;
    maxReach += heap.shift();
    stops++;
  }
  return stops;
}

