import java.util.*;

public class Solution {
    public static int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long maxReach = startFuel;
        int stops = 0, idx = 0;
        while (maxReach < target) {
            while (idx < stations.length && stations[idx][0] <= maxReach) {
                maxHeap.add(stations[idx][1]);
                idx++;
            }
            if (maxHeap.isEmpty()) return -1;
            maxReach += maxHeap.poll();
            stops++;
        }
        return stops;
    }
}

function tallestBillboard(rods) {
  let dp = new Map([[0, 0]]);
  for (const x of rods) {
    const copy = new Map(dp);
    for (const [diff, height] of copy) {
      // Option 1: Add to taller stand
      dp.set(diff + x, Math.max(dp.get(diff + x) || 0, height));
      // Option 2: Add to shorter stand
      const newDiff = Math.abs(diff - x);
      const newHeight = height + Math.min(diff, x);
      dp.set(newDiff, Math.max(dp.get(newDiff) || 0, newHeight));
    }
  }
  return dp.get(0) || 0;
}

