import java.util.*;

public class Solution {
    public static int tallestBillboard(int[] rods) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int x : rods) {
            Map<Integer, Integer> copy = new HashMap<>(dp);
            for (int diff : copy.keySet()) {
                int height = copy.get(diff);
                dp.put(diff + x, Math.max(dp.getOrDefault(diff + x, 0), height));
                int newDiff = Math.abs(diff - x);
                int newHeight = height + Math.min(diff, x);
                dp.put(newDiff, Math.max(dp.getOrDefault(newDiff, 0), newHeight));
            }
        }
        return dp.getOrDefault(0, 0);
    }
}

def tallest_billboard(rods: list[int]) -> int:
    dp = {0: 0}
    for x in rods:
        copy = dict(dp)
        for diff, height in copy.items():
            dp[diff + x] = max(dp.get(diff + x, 0), height)
            new_diff = abs(diff - x)
            new_height = height + min(diff, x)
            dp[new_diff] = max(dp.get(new_diff, 0), new_height)
    return dp.get(0, 0)
